insert into eldervale_private.realm_catalog(id,data) select r->>0,r->1 from jsonb_array_elements($j$[["item:custom_qa_hymn_leaf",{"name":"Kelp hymn leaf","description":"A page of the drowned choir’s hymn book, written on pressed kelp. Scholar Ilse can read it.","icon":"scroll","custom":true,"category":"Quest items","buy":0,"sell":0,"unique":true,"tradeable":false,"untradeable":true,"questItem":true,"keepOnDeath":true,"shopless":true}],["item:custom_qa_corrow_bell",{"name":"Corrow warning bell","description":"A small silver hand-bell, green with two centuries of sea. It still rings true. Scholar Ilse is waiting for it.","icon":"gem","custom":true,"category":"Quest items","buy":0,"sell":0,"unique":true,"tradeable":false,"untradeable":true,"questItem":true,"keepOnDeath":true,"shopless":true}],["item:custom_qa_tidebell",{"name":"Tidebell of Corrow","description":"A bell-shaped silver pendant that hums at low tide. Ring it to return to the Drowned Steps at Saltglass.","icon":"gem","custom":true,"category":"Quest items","buy":0,"sell":0,"unique":true,"tradeable":false,"untradeable":true,"questItem":true,"keepOnDeath":true,"shopless":true}]]$j$::jsonb) r
