-- People, monsters and shortcuts of the arc (fixed ids; the entity trigger fills realm_actors / realm_objects).
select eldervale_private.quest_arc_entities($j$[{"id":"a3c0a000-0004-4000-8000-000000000001","data":{"kind":"npc","name":"Harbourmaster Corwen Tidewell","role":"guard","weapon":"longsword","attackType":"slash","color":5465979,"level":20,"hp":110,"damage":12,"attackSpeed":2.4,"roam":0,"respawn":30,"attackable":false,"hostile":false,"scale":1,"dialogue":"Saltglass harbour. Tides, tolls and trouble. Mostly tolls.","template":"guard","x":306,"z":340,"yaw":180,"questArc":"tide","blueprint":"quest-arcs-v1","blueprintKey":"tide:tidewell"}},{"id":"a3c0a000-0004-4000-8000-000000000002","data":{"kind":"npc","name":"Agathe the Net-Mender","role":"resident","weapon":null,"attackType":"punch","color":8356955,"level":5,"hp":45,"damage":4,"attackSpeed":2.4,"roam":0,"respawn":30,"attackable":false,"hostile":false,"scale":1,"dialogue":"Every net tells a story. Mostly the story is “a crab did this”.","template":"villager","x":316,"z":333,"yaw":-90,"questArc":"tide","blueprint":"quest-arcs-v1","blueprintKey":"tide:agathe"}},{"id":"a3c0a000-0004-4000-8000-000000000003","data":{"kind":"npc","name":"Little Tobin","role":"resident","weapon":null,"attackType":"punch","color":8356955,"level":5,"hp":45,"damage":4,"attackSpeed":2.4,"roam":0,"respawn":30,"attackable":false,"hostile":false,"scale":0.78,"dialogue":"Do you hear the bells? Grown-ups never hear the bells.","template":"villager","x":294,"z":352,"yaw":180,"questArc":"tide","blueprint":"quest-arcs-v1","blueprintKey":"tide:tobin"}},{"id":"a3c0a000-0004-4000-8000-000000000004","data":{"kind":"npc","name":"Grandmother Moss","role":"healer","weapon":null,"attackType":"magic","color":14735023,"level":5,"hp":45,"damage":5,"attackSpeed":2.4,"roam":0,"respawn":30,"attackable":false,"hostile":false,"scale":1,"dialogue":"Mind the bog, mind the eels, mind your manners. In that order.","template":"healer","x":-190,"z":262,"yaw":90,"questArc":"tide","blueprint":"quest-arcs-v1","blueprintKey":"tide:moss"}},{"id":"a3c0a000-0004-4000-8000-000000000005","data":{"kind":"npc","name":"Ferryman Ambrose Reedly","role":"resident","weapon":null,"attackType":"punch","color":8356955,"level":5,"hp":45,"damage":4,"attackSpeed":2.4,"roam":0,"respawn":30,"attackable":false,"hostile":false,"scale":1,"dialogue":"The Mirewater ferry. Fens to the bay by the old channels, if you know the way. I know the way.","template":"villager","x":-178,"z":252,"yaw":90,"questArc":"tide","blueprint":"quest-arcs-v1","blueprintKey":"tide:reedly"}},{"id":"a3c0a000-0004-4000-8000-000000000006","data":{"kind":"npc","name":"Scholar Ilse Quillon","role":"mage","weapon":null,"attackType":"magic","color":6312331,"level":18,"hp":65,"damage":13,"attackSpeed":2.4,"roam":0,"respawn":30,"attackable":false,"hostile":false,"scale":1,"dialogue":"Old Corrow had a library, a choir and a harbour. The sea kept all three. I would like them back.","template":"mage","x":282,"z":340,"yaw":90,"questArc":"tide","blueprint":"quest-arcs-v1","blueprintKey":"tide:ilse"}},{"id":"a3c0a000-0004-4000-8000-000000000007","data":{"kind":"npc","name":"Echo of Old Corrow","role":"mage","weapon":null,"attackType":"magic","color":6312331,"level":18,"hp":65,"damage":13,"attackSpeed":2.4,"roam":0,"respawn":30,"attackable":false,"hostile":false,"scale":1,"dialogue":"(A voice made of many voices, singing very quietly.) Is it time? Is it finally time?","template":"mage","x":3878,"z":3008,"yaw":-90,"questArc":"tide","blueprint":"quest-arcs-v1","blueprintKey":"tide:echo"}},{"id":"a3c0a000-0004-4000-8000-000000000008","data":{"kind":"npc","name":"Bell-Salvager Odile","role":"merchant","weapon":"dagger","attackType":"stab","color":10253389,"level":5,"hp":45,"damage":4,"attackSpeed":2.4,"roam":0,"respawn":30,"attackable":false,"hostile":false,"scale":1,"dialogue":"Everything the sea gives back, I sell. Everything the sea keeps, I dive for.","template":"merchant","x":3820,"z":3404,"yaw":180,"questArc":"tide","blueprint":"quest-arcs-v1","blueprintKey":"tide:salvager","shop":{"harpoon":{"buy":45,"sell":14,"stock":10},"lobsterPot":{"buy":40,"sell":12,"stock":10},"rawSwordfish":{"buy":180,"sell":55,"stock":20},"rawStormfin":{"buy":420,"sell":130,"stock":10},"tidesteelArrowtips":{"buy":30,"sell":9,"stock":300}}}},{"id":"a3c0a000-0004-4000-9000-000000000001","data":{"kind":"monster","name":"Bog eel-thief","species":"imp","attackType":"magic","level":9,"hp":110,"damage":2,"attackSpeed":2.8,"roam":2,"respawn":60,"attackable":true,"hostile":true,"scale":0.55,"template":"imp","x":-196,"z":270,"yaw":0,"maxHit":21,"attackLevel":6,"strengthLevel":5,"defenceLevel":6,"magicLevel":11,"attackBonus":3,"defenceBonuses":{"stab":2,"slash":2,"crush":2,"magic":4,"ranged":2},"xpReward":64,"goldReward":16,"tint":6122299,"eyes":12124026,"breath":10216042,"examine":"It has stolen an eel. It is wearing the eel. Why is it wearing the eel?","loot":[{"item":"ashes","min":1,"max":1,"chance":1,"always":true}],"behavior":"wander","questArc":"tide","blueprint":"quest-arcs-v1","blueprintKey":"tide:eel1"}},{"id":"a3c0a000-0004-4000-9000-000000000002","data":{"kind":"monster","name":"Bog eel-thief","species":"imp","attackType":"magic","level":9,"hp":110,"damage":2,"attackSpeed":2.8,"roam":2,"respawn":60,"attackable":true,"hostile":true,"scale":0.55,"template":"imp","x":-186,"z":272,"yaw":0,"maxHit":21,"attackLevel":6,"strengthLevel":5,"defenceLevel":6,"magicLevel":11,"attackBonus":3,"defenceBonuses":{"stab":2,"slash":2,"crush":2,"magic":4,"ranged":2},"xpReward":64,"goldReward":16,"tint":6122299,"eyes":12124026,"breath":10216042,"examine":"It has stolen an eel. It is wearing the eel. Why is it wearing the eel?","loot":[{"item":"ashes","min":1,"max":1,"chance":1,"always":true}],"behavior":"wander","questArc":"tide","blueprint":"quest-arcs-v1","blueprintKey":"tide:eel2"}},{"id":"a3c0a000-0004-4000-9000-000000000003","data":{"kind":"monster","name":"Drowned chorister","species":"revenant","attackType":"magic","level":28,"hp":280,"damage":4,"attackSpeed":2.8,"roam":2,"respawn":60,"attackable":true,